                   {row:2,t:arrB,lab:"从库 B 收到",c:"--s2"},
                   {row:3,t:r1,lab:"第 1 次刷新 → 从库 A",c:seen1?"--ok":"--ink-3",val:seen1?"看到评论#42":"没有评论#42"},
                   {row:3,t:r2,lab:"第 2 次刷新 → 从库 B",c:ok?"--ok":"--crit",val:seen2?"看到评论#42":"评论#42 消失了 ✗"}],
            ok, why: ok?'两次读落到的副本进度一致（或都还没收到），没有出现倒退。'
