                   {row:1,t:arrA2,lab:"从库 A 收到「回答」",c:"--s3"},
                   {row:3,t:readT,lab:"观察者同时读两个分区",c:ok?"--ok":"--crit",
                    val:ok?(seeQ?"问题 → 回答 ✓":"两条都还没到"):"只看到「回答」，没有「问题」✗"}],
            ok, why: ok?'两个分区的复制进度足够接近，因果顺序没有被打乱。'
                       :'「回答」在因果上依赖「问题」，但它们落在不同分区、复制进度不同。观察者先看到了果，还没看到因。',
            fix:"修复是把有因果关系的写入放进同一个分区，或在应用层显式追踪因果依赖（Part 1 的向量时钟）。"};
  }}
];
function draw1(){
