  Y.forEach((y,i)=>{
    svg.appendChild(el("line",{x1:L,y1:y,x2:R,y2:y,stroke:cv("--grid"),"stroke-width":1.5,"stroke-dasharray":i===3?"4 4":""}));
    svg.appendChild(el("text",{x:L-10,y:y+4,fill:cv(RC[i]),"font-size":11.5,"font-weight":700,"text-anchor":"end","font-family":cv("--sans")},ROW[i]));
  });
  for(let t=0;t<=TMAX;t+=200){
