    svg.appendChild(el("text",{x:x,y:y-13,fill:cv("--ink-2"),"font-size":10,"text-anchor":x>R-140?"end":"middle","font-family":cv("--sans")},m.lab));
    if(m.val) svg.appendChild(el("text",{x:x,y:y+20,fill:cv(m.c),"font-size":10.5,"font-weight":600,"text-anchor":x>R-140?"end":"middle","font-family":cv("--sans")},m.val));
  });
  $("#o1").innerHTML='<div class="note '+(S.ok?"ok":"crit")+'" style="margin:0">'+
