    (S.ok?"这次没有触发异常":"违反了 "+SCEN1[sc1].g+"（"+SCEN1[sc1].t.slice(2)+"）")+'</div>'+
    '<p>'+S.why+'</p><p style="margin-bottom:0"><strong>'+S.fix+'</strong></p></div>';
}
$$("#sc1 button").forEach(b=>b.onclick=()=>{$$("#sc1 button").forEach(x=>x.classList.remove("act"));
  b.classList.add("act"); sc1=+b.dataset.s; draw1();});
$("#r1a").oninput=draw1; $("#r1b").oninput=draw1; draw1();

/* ══════════════════════════════════════════════════════════════════
   实验 2 · 一致性判定器（真的在跑穷举）
   ══════════════════════════════════════════════════════════════════ */
const INIT="⊥";
const HIST=[
 {n:"① 教科书式的线性一致",d:"C1 写完并返回后，C2 才开始读 —— 必须读到新值，而它确实读到了。",
  ops:[{c:0,k:"w",v:"A",s:0,e:3},{c:1,k:"r",v:"A",s:5,e:8}]},
 {n:"② 重叠区间里读到旧值",d:"C2 的读与 C1 的写在时间上重叠。线性一致允许它读到旧值——因为可以把读线性化到写之前。",
  ops:[{c:0,k:"w",v:"A",s:2,e:8},{c:1,k:"r",v:INIT,s:3,e:6},{c:2,k:"r",v:"A",s:10,e:12}]},
 {n:"③ 陈旧读",d:"C1 的写早已返回，C2 之后才开始读，却读到了初始值。线性一致被打破，但仍能自圆其说。",
  ops:[{c:0,k:"w",v:"A",s:0,e:3},{c:1,k:"r",v:INIT,s:5,e:8}]},
 {n:"④ 两个观察者，相反的顺序",d:"两个并发写；C3 看到 A→B，C4 看到 B→A。不存在单一全序能同时解释两人，但因果上没有矛盾。",
  ops:[{c:0,k:"w",v:"A",s:0,e:2},{c:1,k:"w",v:"B",s:1,e:3},
       {c:2,k:"r",v:"A",s:5,e:6},{c:2,k:"r",v:"B",s:8,e:9},
       {c:3,k:"r",v:"B",s:5,e:6},{c:3,k:"r",v:"A",s:8,e:9}]},
 {n:"⑤ 因果倒置",d:"C2 读到 A 之后才写 B，所以 A 因果先于 B。C3 却先看到 B，又看回了 A。",
  ops:[{c:0,k:"w",v:"A",s:0,e:2},{c:1,k:"r",v:"A",s:3,e:4},{c:1,k:"w",v:"B",s:5,e:7},
       {c:2,k:"r",v:"B",s:9,e:10},{c:2,k:"r",v:"A",s:12,e:13}]},
 {n:"⑥ 读不到自己的写",d:"C1 自己写完，紧接着自己读，却读到初始值。最基本的会话保证被破坏。",
  ops:[{c:0,k:"w",v:"A",s:0,e:2},{c:0,k:"r",v:INIT,s:4,e:6},{c:1,k:"r",v:"A",s:8,e:10}]}
];
let hi=0;

function dfsOrder(ops, idx, canPlace){
  const placed=new Set(), out=[]; let steps=0;
  function go(cur){
    if(++steps>250000) return false;
    if(out.length===idx.length) return true;
    for(const j of idx){
      if(placed.has(j)) continue;
      if(!canPlace(j,placed)) continue;
      if(ops[j].k==="r" && ops[j].v!==cur) continue;
      placed.add(j); out.push(j);
      if(go(ops[j].k==="w"?ops[j].v:cur)) return true;
      out.pop(); placed.delete(j);
    }
    return false;
  }
  return go(INIT)? out.slice() : null;
}
const allIdx=ops=>ops.map((_,i)=>i);
// 线性一致：尊重真实时间序
function checkLin(ops){
  return dfsOrder(ops, allIdx(ops), (j,placed)=>{
    for(let i=0;i<ops.length;i++) if(!placed.has(i)&&i!==j&&ops[i].e<ops[j].s) return false;
    return true;});
}
// 顺序一致：只保留每个客户端的程序序
function checkSeq(ops){
  return dfsOrder(ops, allIdx(ops), (j,placed)=>{
    for(let i=0;i<ops.length;i++) if(!placed.has(i)&&i!==j&&ops[i].c===ops[j].c&&ops[i].s<ops[j].s) return false;
    return true;});
}
// 因果序：程序序 + 写→读依赖，取传递闭包
function causalReach(ops){
  const n=ops.length, adj=Array.from({length:n},()=>[]);
  for(let i=0;i<n;i++)for(let j=0;j<n;j++){
    if(i===j)continue;
    if(ops[i].c===ops[j].c&&ops[i].s<ops[j].s) adj[i].push(j);
    if(ops[i].k==="w"&&ops[j].k==="r"&&ops[j].v===ops[i].v) adj[i].push(j);
  }
  const R=Array.from({length:n},()=>new Array(n).fill(false));
  for(let s=0;s<n;s++){const st=[s],seen=new Set([s]);
    while(st.length){const x=st.pop();for(const y of adj[x])if(!seen.has(y)){seen.add(y);R[s][y]=true;st.push(y);}}}
  return R;
}
// 因果一致：每个客户端可以有各自的串行化，但都要尊重因果序
function checkCausal(ops){
  const R=causalReach(ops), out={};
  for(const c of [...new Set(ops.map(o=>o.c))]){
    const idx=[]; ops.forEach((o,i)=>{ if(o.k==="w"||o.c===c) idx.push(i); });
    const r=dfsOrder(ops, idx, (j,placed)=>{
      for(const i of idx) if(!placed.has(i)&&i!==j&&R[i][j]) return false;
      return true;});
    if(!r) return null;
    out[c]=r;
  }
  return out;
}
// 版本序：写按真实开始时间排序，初始值为版本 0
function versions(ops){
  const m={[INIT]:0}; let v=0;
  ops.filter(o=>o.k==="w").sort((a,b)=>a.s-b.s).forEach(o=>{m[o.v]=++v;});
  return m;
}
function checkRYW(ops){
  const V=versions(ops), bad=[];
  for(const c of [...new Set(ops.map(o=>o.c))]){
    const mine=ops.filter(o=>o.c===c).sort((a,b)=>a.s-b.s);
    let lastW=null;
    for(const o of mine){
      if(o.k==="w") lastW=o;
      else if(lastW && V[o.v]<V[lastW.v]) bad.push("C"+(c+1)+" 写入 "+lastW.v+" 之后却读到了更旧的 "+o.v);
    }
  }
  return bad;
}
function checkMono(ops){
  const V=versions(ops), bad=[];
  for(const c of [...new Set(ops.map(o=>o.c))]){
    const rs=ops.filter(o=>o.c===c&&o.k==="r").sort((a,b)=>a.s-b.s);
    for(let i=1;i<rs.length;i++)
      if(V[rs[i].v]<V[rs[i-1].v]) bad.push("C"+(c+1)+" 先读到 "+rs[i-1].v+" 又读回了更旧的 "+rs[i].v);
  }
  return bad;
}
function fmtSeq(ops,order){
  return order.map(i=>{const o=ops[i];return (o.k==="w"?"w":"r")+"("+o.v+")@C"+(o.c+1);}).join("  →  ");
}
function draw2(){
  const H=HIST[hi], ops=H.ops;
  const svg=$("#sv2"); svg.innerHTML="";
  const W=720,L=64,R=698, clients=[...new Set(ops.map(o=>o.c))].sort((a,b)=>a-b);
  const TMAX=Math.max(...ops.map(o=>o.e))+2;
  const xt=t=>L+t/TMAX*(R-L);
  const rowY=c=>34+clients.indexOf(c)*34;
  const H2=34+clients.length*34+26;
  svg.setAttribute("viewBox","0 0 720 "+Math.max(H2+16,120));
  for(let t=0;t<=TMAX;t+=2){
    svg.appendChild(el("line",{x1:xt(t),y1:16,x2:xt(t),y2:H2-16,stroke:cv("--grid"),"stroke-width":1,opacity:.4}));
  }
  svg.appendChild(el("line",{x1:L,y1:H2-14,x2:R,y2:H2-14,stroke:cv("--axis"),"stroke-width":1}));
  svg.appendChild(el("text",{x:R,y:H2,fill:cv("--ink-3"),"font-size":9.5,"text-anchor":"end","font-family":cv("--sans")},"真实时间 →"));
  clients.forEach(c=>{
    const y=rowY(c);
    svg.appendChild(el("text",{x:L-12,y:y+4,fill:cv("--ink-2"),"font-size":11.5,"font-weight":700,"text-anchor":"end","font-family":cv("--sans")},"C"+(c+1)));
  });
  const CC=["--s1","--s3","--s7","--s2"];
  ops.forEach(o=>{
    const y=rowY(o.c), x1=xt(o.s), x2=xt(o.e), col=cv(CC[o.c%4]);
    if(o.k==="w") svg.appendChild(el("rect",{x:x1,y:y-11,width:Math.max(x2-x1,14),height:22,rx:5,fill:col}));
    else svg.appendChild(el("rect",{x:x1,y:y-11,width:Math.max(x2-x1,14),height:22,rx:5,fill:"none",stroke:col,"stroke-width":2}));
    svg.appendChild(el("text",{x:(x1+x2)/2,y:y+4,fill:o.k==="w"?"#fff":cv("--ink"),"font-size":11,"font-weight":650,
      "text-anchor":"middle","font-family":cv("--mono")},(o.k==="w"?"w(":"r(")+o.v+")"));
  });
  // 判定
  const lin=checkLin(ops), seq=checkSeq(ops), cau=checkCausal(ops),
        ryw=checkRYW(ops), mono=checkMono(ops);
  const cell=(k,ok,note)=>'<div class="vc"><div class="k">'+k+'</div><div class="v '+(ok?"y":"n")+'">'+
    (ok?"✓ 满足":"✗ 违反")+'</div>'+(note?'<div style="font-size:11px;color:var(--ink-3);margin-top:3px">'+note+'</div>':'')+'</div>';
  $("#vd2").innerHTML=cell("线性一致 linearizable",!!lin)+cell("顺序一致 sequential",!!seq)+
    cell("因果一致 causal",!!cau)+cell("读己之写 RYW",ryw.length===0)+cell("单调读 monotonic",mono.length===0);
  // 解释
  let h='<div class="card" style="margin:0"><div class="card-t">'+H.n+'</div><p style="margin-bottom:12px">'+H.d+'</p>';
  if(lin) h+='<p style="margin:0 0 6px"><strong style="color:var(--ok)">找到一个线性化顺序</strong>（尊重真实时间 + 每个读都读到最近的写）：<br><span class="chip" style="margin-top:5px;display:inline-block">'+fmtSeq(ops,lin)+'</span></p>';
  else{
    h+='<p style="margin:0 0 6px"><strong style="color:var(--crit)">不存在合法的线性化顺序</strong>：任何尊重真实时间序的排列都会让某个读返回错误的值。</p>';
    if(seq) h+='<p style="margin:0 0 6px"><strong style="color:var(--ok)">但存在一个顺序一致的全序</strong>（去掉真实时间约束后）：<br><span class="chip" style="margin-top:5px;display:inline-block">'+fmtSeq(ops,seq)+'</span><br><span style="font-size:12.5px;color:var(--ink-3)">这就是线性一致与顺序一致的唯一分界：是否必须尊重真实时间。</span></p>';
    else{
      h+='<p style="margin:0 0 6px"><strong style="color:var(--crit)">也不存在顺序一致的全序</strong>：不同客户端观察到的顺序互相矛盾，凑不出一个大家都同意的排列。</p>';
      if(cau){
        h+='<p style="margin:0 0 6px"><strong style="color:var(--ok)">但因果一致成立</strong> —— 允许每个客户端有各自的串行化，只要都尊重因果序：</p><div style="font-size:12.5px">';
        for(const c in cau) h+='<div style="margin:3px 0">C'+(+c+1)+' 眼中的顺序：<span class="chip">'+fmtSeq(ops,cau[c])+'</span></div>';
        h+='</div><p style="margin:8px 0 0;font-size:12.5px;color:var(--ink-3)">两个写是<strong>并发</strong>的，因果上没有先后，所以不同观察者看到不同顺序并不矛盾。这正是因果一致比顺序一致可用性高的原因。</p>';
      } else h+='<p style="margin:0 0 6px"><strong style="color:var(--crit)">因果一致也不成立</strong>：有客户端看到了"果"却看不到"因"，或看到了因果颠倒的顺序。</p>';
    }
  }
  if(ryw.length) h+='<p style="margin:10px 0 0;color:var(--crit);font-size:13.5px"><strong>读己之写被破坏：</strong>'+ryw.join("；")+'</p>';
  if(mono.length) h+='<p style="margin:6px 0 0;color:var(--crit);font-size:13.5px"><strong>单调读被破坏：</strong>'+mono.join("；")+'</p>';
  h+='</div>';
  $("#ex2").innerHTML=h;
}
$("#sc2").innerHTML=HIST.map((x,i)=>'<button data-i="'+i+'"'+(i===0?' class="act"':'')+'>'+x.n+'</button>').join("");
$$("#sc2 button").forEach(b=>b.onclick=()=>{$$("#sc2 button").forEach(x=>x.classList.remove("act"));
  b.classList.add("act"); hi=+b.dataset.i; draw2();});
draw2();
EOF
